    /// <summary>按地区名精确/包含匹配（大小写不敏感，供「查找并定位地区」用）。</summary>
    public static RegionRow? FindRegion(string? keyword)
        => Regions.FirstOrDefault(r => r.Name == keyword)
           ?? Regions.FirstOrDefault(r => !string.IsNullOrWhiteSpace(keyword)
                && r.Name.Contains(keyword!, StringComparison.OrdinalIgnoreCase));

