    /// <summary>按型材代号精确/包含匹配（供「快速查找型材」用）。</summary>
    public static ColumnProfile? FindColumn(string? keyword)
        => Columns.FirstOrDefault(c => c.Code == keyword)
           ?? Columns.FirstOrDefault(c => !string.IsNullOrWhiteSpace(keyword)
                && c.Code.Contains(keyword!, StringComparison.OrdinalIgnoreCase));

