    /// <summary>左框型材查（空 = 表内第一行）。</summary>
    public static ColumnProfile? FindUnitColumnLeft(string? keyword) => FindIn(UnitColumnsLeft, keyword);

    /// <summary>右框型材查（空 = 表内第一行）。</summary>
    public static ColumnProfile? FindUnitColumnRight(string? keyword) => FindIn(UnitColumnsRight, keyword);

    private static ColumnProfile FindIn(IReadOnlyList<ColumnProfile> table, string? keyword)
    {
        if (string.IsNullOrWhiteSpace(keyword)) return table[0];
        return table.FirstOrDefault(c => c.Code == keyword)
            ?? table.FirstOrDefault(c => c.Code.Contains(keyword!, StringComparison.OrdinalIgnoreCase))
            ?? table[0];
    }
